import { Component } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { MenuComponent } from './Pages/Menu/menu.component';
import { ProfilesComponent } from './Pages/Profiles/profiles.component';
import { SkillsComponent } from './Pages/Skills/skills.component';
import { ProyectsComponent } from './Pages/Proyects/proyects.component';
import { ExpeciencieComponent } from './Pages/Expeciencie/expeciencie.component';
import { LearningComponent } from './Pages/Learning/learning.component';
import { ExtrasComponent } from './Pages/Extras/extras.component';
import { RouterModule } from '@angular/router';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    RouterModule,
    MenuComponent,
    ProfilesComponent,
    SkillsComponent,
    ProyectsComponent,
    ExpeciencieComponent,
    LearningComponent,
    ExtrasComponent
  ],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  constructor(private translate: TranslateService) {
    this.translate.setDefaultLang('es');

    if (typeof window !== 'undefined' && window.localStorage) {
      const savedLang = localStorage.getItem('lang');
      if (savedLang) {
        this.translate.use(savedLang);
      }
    }
  }

  changeLang(lang: string) {
    this.translate.use(lang);
    if (typeof window !== 'undefined' && window.localStorage) {
      localStorage.setItem('lang', lang);
    }
  }
}
<body>


  <div id="main-container">
    <app-menu></app-menu>

    <section id="inicio">
      <app-profiles></app-profiles>
    </section>

    <section id="tecnologias">
      <app-skills></app-skills>
    </section>

    <section id="experience-learning-section">
      <section id="experiencia">
        <app-expeciencie class="experience-learning-card"></app-expeciencie>
      </section>

      <section id="formacion">
        <app-learning class="experience-learning-card"></app-learning>
      </section>
    </section>

    <section id="proyectos">
      <app-proyects></app-proyects>
    </section>

    <section id="extras">
      <app-extras></app-extras>
    </section>
  </div>

  <footer id="footer">
    <p>© 2026 <strong>Marcos Bazán Fernández</strong> · Todos los derechos reservados.</p>
  </footer>
</body>
